// ===== CONFIGURACIÓN DE LABORATORIO (editar antes de activar) =====
// Todos los correos van a este destinatario de prueba, NO al paciente: los datos del laboratorio son sintéticos.
const LAB_RECIPIENT = 'LAB_RECIPIENT_AQUI';
// ====================================================================
// URL pública de citas-api (túnel) SIN barra final. Ej.: https://algo.trycloudflare.com
const API_BASE_URL = 'API_BASE_URL_AQUI';
const HORAS_VENTANA = 24;
if (LAB_RECIPIENT === 'LAB_RECIPIENT_AQUI' || API_BASE_URL === 'API_BASE_URL_AQUI') {
  throw new Error('Configura LAB_RECIPIENT y API_BASE_URL antes de ejecutar');
}
const fmtLocal = (d) => d.toFormat("yyyy-MM-dd'T'HH:mm:ss");
const ahora = $now;
return [{ json: { apiBaseUrl: API_BASE_URL, labRecipient: LAB_RECIPIENT, desde: fmtLocal(ahora), hasta: fmtLocal(ahora.plus({ hours: HORAS_VENTANA })) } }];

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// El backend envia hora local de Bogota SIN zona horaria: se muestra tal cual, sin convertir.
const fmt = (iso) => { const s = String(iso); const conZona = /[zZ]$|[+-]\d{2}:?\d{2}$/.test(s); const d = new Date(conZona ? s : s + 'Z'); return isNaN(d) ? esc(iso) : d.toLocaleString('es-CO', { timeZone: conZona ? 'America/Bogota' : 'UTC', dateStyle: 'full', timeStyle: 'short' }); };
const cfg = $('Calcular ventana').first().json;
const citas = $input.all().map((i) => i.json).flatMap((j) => (Array.isArray(j) ? j : j.citaId ? [j] : []));
// Deduplicación: no recordar dos veces la misma cita en el mismo horario.
const memoria = $getWorkflowStaticData('global');
memoria.recordadas = memoria.recordadas ?? {};
const salida = [];
for (const c of citas) {
  if (c.estado !== 'APPROVED') continue;
  const clave = c.citaId + '|' + c.inicio;
  if (memoria.recordadas[clave]) continue;
  salida.push({ json: { clave, citaId: c.citaId, to: cfg.labRecipient,
    subject: '[FCV Lab] Recordatorio de cita #' + c.citaId,
    html: '<p>Hola ' + esc(c.pacienteNombre) + ',</p><p>Te recordamos tu cita:</p><ul><li><b>Fecha:</b> ' + fmt(c.inicio)
      + '</li><li><b>Profesional:</b> ' + esc(c.profesionalNombre) + '</li><li><b>Especialidad:</b> ' + esc(c.especialidadNombre)
      + '</li><li><b>Sede:</b> ' + esc(c.sedeNombre) + '</li></ul><p style="color:#666">Correo de laboratorio. Destinatario original: ' + esc(c.pacienteEmail) + '</p>' } });
}
return salida;

// Se ejecuta solo si Gmail confirmó el envío: marca la cita como recordada y deja trazabilidad.
const memoria = $getWorkflowStaticData('global');
memoria.recordadas = memoria.recordadas ?? {};
const previo = $('Preparar recordatorios').all();
const resultados = [];
for (const [idx, item] of $input.all().entries()) {
  const origen = previo[idx]?.json ?? {};
  if (origen.clave) memoria.recordadas[origen.clave] = new Date().toISOString();
  resultados.push({ json: { resultado: 'SENT', citaId: origen.citaId, gmailId: item.json.id ?? null, momento: new Date().toISOString() } });
}
return resultados;
